  nodes,
  paths,
  aliases,
  selectedPath,
  onSelect,
}: {
  nodes: GraphNode[];
  selectedPath?: string;
  paths: string[];
  aliases: RepositoryAlias[];
  onSelect: (path: string, node?: GraphNode) => void;
}) {
  const tree = useMemo(
    () => buildTree(nodes.filter((node) => node.kind === "module"), paths, aliases),
    [nodes, paths, aliases],
  );
  return (
    <div className="file-tree">
      {tree.map((item) => (
        <TreeRow
          key={item.path}
          item={item}
          depth={0}
          selectedPath={selectedPath}
          onSelect={onSelect}
        />
      ))}
    </div>
  );
}

