  nodes,
  paths,
  aliases,
  selectedPath,
  onSelect,
}: {
  nodes: GraphNode[];
  selectedPath?: string;
  paths: string[];
  aliases: RepositoryAlias[];
  onSelect: (path: string, node?: GraphNode) => void;
}) {
