class RepositorySnapshot:
    fingerprint: str
    files: tuple[IndexedFileState, ...]
    aliases: tuple[IndexedAliasState, ...] = ()

    @property
    def paths(self) -> frozenset[str]:
        return frozenset(item.path for item in self.files)

