def _bedrock_tool_config(tools: list[Any], choice: dict[str, Any] | None) -> dict[str, Any]:
    """Translate Waypoint's Anthropic-shaped tool declarations into Converse's `toolConfig`.

    Input: tools - list of Anthropic-style `{"name", "description", "input_schema"}`
    dicts; choice - an Anthropic-style `tool_choice` dict (`{"type": "auto"}` or
    `{"type": "tool", "name": ...}`), or None. Converse's forced single-tool
    choice (`{"tool": {"name": ...}}`) is not guaranteed to be honored by every
    model family Bedrock hosts, unlike Anthropic's own API - callers should treat
    a forced choice as a hint the model may still ignore. Called once per
    `BedrockConverseMessages.create` call to build the request's `toolConfig`.
    """
    tool_specs = [
        {
            "toolSpec": {
                "name": str(tool["name"]),
                "description": str(tool.get("description", "")),
                "inputSchema": {"json": tool.get("input_schema", {"type": "object"})},
            }
        }
        for tool in tools
    ]
    tool_choice: dict[str, Any] = {"auto": {}}
    if choice and choice.get("type") == "tool":
        tool_choice = {"tool": {"name": str(choice["name"])}}
    return {"tools": tool_specs, "toolChoice": tool_choice}

def __init__(self, session: AnalysisSession) -> None:
        self.session = session
        self._agents: dict[tuple[str, str], RepositoryAgentService] = {}

def compare_endpoints(
        self,
        request: AgenticComparisonRequest,
        endpoints: list[tuple[str, str]],
        *,
        parallel: bool = True,
    ) -> AgenticComparisonReport:
        if not 2 <= len(endpoints) <= 4 or len(set(endpoints)) != len(endpoints):
            raise ValueError("Agentic comparison requires two to four distinct endpoints")
        runs: list[AgenticModelRun] = []
        failures: list[ModelComparisonFailure] = []
        # Build retrieval indexes sequentially before model threads start. SQLite WAL
        # initialization can otherwise race when both endpoint agents are constructed.
        agents: dict[tuple[str, str], RepositoryAgentService] = {}
        for endpoint in endpoints:
            agent = self._agents.get(endpoint)
            if agent is None:
                agent = RepositoryAgentService(self.session)
                self._agents[endpoint] = agent
            agents[endpoint] = agent
        workers = len(endpoints) if parallel else 1
        with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="agentic-comparison") as pool:
            futures = {}
            for endpoint in endpoints:
                trace_id = f"agentic-{uuid.uuid4().hex}"
                futures[endpoint] = (
                    pool.submit(self._run, endpoint, request, trace_id, agents[endpoint]),
                    time.perf_counter(),
                    trace_id,
                )
            for endpoint, (future, started, trace_id) in futures.items():
                try:
                    runs.append(future.result())

def _client(self) -> Any:
        """Returns the active model provider client, translating provider setup failures into `AgentUnavailableError`.

        Input: none. Called by `answer` below and, directly, by
        backend/app/agent/onboarding.py and backend/app/agent/issues.py (via
        `self.repository_agent._client()` / `self.agent._client()`) so those sibling
        agents reuse the same provider-selection and error-wrapping logic instead of
        calling `model_provider_router.client()` themselves.
        """
        try:
            return model_provider_router.client()
        except (ImportError, RuntimeError) as exc:
            raise AgentUnavailableError(
                f"No model provider is available: {exc}"
            ) from exc

