        Input: none. Called by `answer` below and, directly, by
        backend/app/agent/onboarding.py and backend/app/agent/issues.py (via
        `self.repository_agent._client()` / `self.agent._client()`) so those sibling
        agents reuse the same provider-selection and error-wrapping logic instead of
        calling `model_provider_router.client()` themselves.
        """
        try:
            return model_provider_router.client()
        except (ImportError, RuntimeError) as exc:
            raise AgentUnavailableError(
                f"No model provider is available: {exc}"
            ) from exc

def consistent_count(self) -> "SearchOutput":
        if self.count != len(self.results):
            raise ValueError("count does not match the number of results")
        return self

def correction_envelope(
    *, code: str, tool: str, message: str, errors: list[dict[str, Any]] | None = None,
    retryable: bool = True,
) -> str:
    """Stable machine-readable feedback returned to a model after validation fails."""

    return json.dumps({
        "ok": False,
        "error": {
            "code": code,
            "tool": tool,
            "message": message,
            "retryable": retryable,
            "violations": errors or [],
            "instruction": (
                "Correct only the invalid fields and call the tool again."
                if retryable else "Do not retry this tool; Waypoint must repair its server result."
            ),
        },
    }, ensure_ascii=False)

