def is_video_url(url):
    """Check if URL looks like a video URL."""
    try:
        parsed = urlparse(url)
        domain = parsed.netloc.lower()

        # Remove www. prefix
        if domain.startswith('www.'):
            domain = domain[4:]

        # Check if it's a valid video domain
        for valid_domain in VALID_DOMAINS:
            if valid_domain in domain:
                return True

        return False
    except:
        return False

