 1 | #!/usr/bin/env node
 2 | /**
 3 |  * youtube-to-vtt.cjs
 4 |  *
 5 |  * Turn a YouTube (or any yt-dlp-supported) video URL into a single normalized
 6 |  * WebVTT transcript file WITHOUT downloading the video.
 7 |  *
 8 |  *   - Resolves yt-dlp: PATH first, then a managed venv at
 9 |  *     ~/.hax-skills/yt-dlp-venv (auto-created + pip-installed on first run so
10 |  *     it works on PEP 668 / externally-managed systems without sudo).
11 |  *   - Extracts subtitles only via --skip-download: tries manual subs first,
12 |  *     then YouTube auto-generated captions.
13 |  *   - Normalizes the sidecars yt-dlp emits (transcript.<lang>.vtt, etc.) to a
14 |  *     single deterministic <output-dir>/transcript.vtt.
15 |  *   - Prints a JSON status line and exits non-zero with a clear message if no
16 |  *     captions are available (treated as a soft failure by callers).
17 |  *
18 |  * Usage:
19 |  *   node youtube-to-vtt.cjs <watch-url> <output-dir> [--lang en]
20 |  *
21 |  * --lang defaults to "en".
22 |  *
23 |  * Leverages the yt-dlp engine (and the `yt-dlp` skill conventions); this script
24 |  * adds the subtitle/VTT extraction + normalization that the yt-dlp skill's
25 |  * download scripts do not provide.
26 |  */
27 | const fs = require("fs");
28 | const os = require("os");
29 | const path = require("path");
30 | const { execFileSync, spawnSync } = require("child_process");
31 | 
32 | const VENV_DIR = path.join(os.homedir(), ".hax-skills", "yt-dlp-venv");
33 | 
34 | function parseFlags(argv) {
35 |   const flags = { lang: "en" };
36 |   for (let i = 0; i < argv.length; i++) {
37 |     const a = argv[i];
38 |     if (a === "--lang") {
39 |       flags.lang = argv[++i];
40 |     }
41 |   }
42 |   return flags;
43 | }
44 | 
45 | function isYouTubeUrl(url) {
46 |   return /^https?:\/\/(www\.youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/|www\.youtube\.com\/shorts\/)/i.test(
47 |     url,
48 |   );
49 | }
50 | 
51 | // Find the yt-dlp executable: PATH first, then the managed venv (auto-created).
52 | function resolveYtDlp() {
53 |   // 1. PATH
54 |   const which = spawnSync("which", ["yt-dlp"], { encoding: "utf8" });
55 |   if (which.status === 0) {
56 |     const p = which.stdout.trim();
57 |     if (p) {
58 |       return { bin: p, source: "path", installed: false };
59 |     }
60 |   }
61 |   // 2. Managed venv
62 |   const venvBin = path.join(VENV_DIR, "bin", "yt-dlp");
63 |   if (fs.existsSync(venvBin)) {
64 |     return { bin: venvBin, source: "venv", installed: false };
65 |   }
66 |   // 3. Provision the venv, then use it
67 |   provisionVenv();
68 |   return { bin: venvBin, source: "venv", installed: true };
69 | }
70 | 
71 | function provisionVenv() {
72 |   fs.mkdirSync(path.dirname(VENV_DIR), { recursive: true });
73 |   // Create the venv (system-site packages off; upgrade pip quietly).
74 |   execFileSync("python3", ["-m", "venv", VENV_DIR], { stdio: "pipe" });
75 |   const venvPip = path.join(VENV_DIR, "bin", "pip");
76 |   execFileSync(venvPip, ["install", "--quiet", "--upgrade", "pip"], {
77 |     stdio: "pipe",
78 |   });
79 |   execFileSync(venvPip, ["install", "--quiet", "yt-dlp"], { stdio: "pipe" });
80 | }
81 | 
82 | // Run yt-dlp with the given args (argv array after the binary); returns status.
83 | function runYtDlp(bin, args) {
84 |   const res = spawnSync(bin, args, { encoding: "utf8" });
85 |   return {
86 |     status: res.status,
87 |     stdout: res.stdout || "",
88 |     stderr: res.stderr || "",
89 |   };
90 | }
