.component {
  /* Avoid creating unnecessary intermediate properties */
  --my-component-margin: var(--ddd-spacing-4);
  --my-component-color: var(--ddd-primary-13);
  margin: var(--my-component-margin);
  color: var(--my-component-color);
}
```

