                if loc.territory:
                    bcp47 = f"{loc.language}-{loc.territory}"
                    display = loc.get_display_name("en")
                    if bcp47 not in seen:
                        seen.add(bcp47)
                        languages.append(LanguageResponse(code=bcp47, name=display))
                    continue
            except Exception:
                pass

        # Fallback: bare language code
