export function useRegisterModels() {
  const queryClient = useQueryClient()
  const { toast } = useToast()
  const { t } = useTranslation()

  return useMutation({
    mutationFn: ({
      credentialId,
      models,
    }: {
      credentialId: string
      models: RegisterModelData[]
    }) => credentialsApi.registerModels(credentialId, { models }),
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: MODEL_QUERY_KEYS.models })
      queryClient.invalidateQueries({ queryKey: CREDENTIAL_QUERY_KEYS.all })

      if (result.created > 0) {
        toast({
          title: t('common.success'),
          description: t('apiKeys.syncSuccess', { discovered: (result.created + result.existing).toString(), new: result.created.toString() }),
        })
      } else {
        toast({
          title: t('common.success'),
          description: t('apiKeys.syncNoNew', { count: result.existing }),
        })
      }
    },
    onError: (error: unknown) => {
      toast({
        title: t('common.error'),
        description: getApiErrorKey(error, t('apiKeys.syncFailed')),
        variant: 'destructive',
      })
    },
  })
}

